"""Run the real CLI under the public child guard, like the verifier does."""
import importlib.util, json, os, selectors, subprocess, sys, time
BASE='/workspace'
spec=importlib.util.spec_from_file_location('cg', BASE+'/child_guard.py')
guard=importlib.util.module_from_spec(spec); spec.loader.exec_module(guard)

def run(data, timeout=180):
    env=dict(PATH='/usr/local/bin:/usr/bin:/bin',HOME='/workspace',LANG='C',LC_ALL='C',
             TMPDIR='/workspace/tmp',PYTHONHASHSEED='0',PYTHONDONTWRITEBYTECODE='1',
             PYTHONUNBUFFERED='1',OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1')
    t=time.time()
    p=subprocess.Popen([sys.executable,'-I','-B',BASE+'/launch.py',BASE+'/project'],
                       stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                       env=env,cwd=BASE,preexec_fn=guard.restrict,close_fds=True)
    sel=selectors.DefaultSelector(); out=[bytearray(),bytearray()]; off=0
    if isinstance(data,str): data=data.encode()
    for s in (p.stdin,p.stdout,p.stderr): os.set_blocking(s.fileno(),False)
    sel.register(p.stdin,selectors.EVENT_WRITE,-1)
    sel.register(p.stdout,selectors.EVENT_READ,0); sel.register(p.stderr,selectors.EVENT_READ,1)
    deadline=time.monotonic()+timeout
    while sel.get_map():
        rem=deadline-time.monotonic()
        if rem<=0: raise TimeoutError('child timeout')
        for key,_ in sel.select(min(.1,rem)):
            stream,index=key.fileobj,key.data
            if index==-1:
                try: off+=os.write(stream.fileno(),data[off:off+65536])
                except BlockingIOError: continue
                except BrokenPipeError: off=len(data)
                if off==len(data): sel.unregister(stream); stream.close()
            else:
                cap=(256*1024**2,1024**2)[index]
                try: block=os.read(stream.fileno(),min(65536,cap-len(out[index])+1))
                except BlockingIOError: continue
                if not block: sel.unregister(stream); stream.close()
                else:
                    out[index].extend(block)
                    if len(out[index])>cap: raise ValueError('child output cap')
    status=p.wait(timeout=max(.001,deadline-time.monotonic()))
    sel.close()
    for s in (p.stdin,p.stdout,p.stderr): s.close()
    dt=time.time()-t
    return status, bytes(out[0]), bytes(out[1]), dt
PYEOF
